<?php require_once __DIR__.'/../config/db.php'; require_role('usuario');$pageTitle='Mis resultados';$s=$pdo->prepare('SELECT r.*,a.title FROM results r JOIN activities a ON a.id=r.activity_id WHERE r.user_id=? ORDER BY r.created_at DESC');$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();require __DIR__.'/../partials/header.php'; ?><h1>Mis resultados</h1><div class="panel"><div class="table-wrap"><table><thead><tr><th>Actividad</th><th>Puntaje</th><th>Porcentaje</th><th>Fecha</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['title'])?></td><td><?=$r['score']?> / <?=$r['total']?></td><td><?= $r['total']?round($r['score']/$r['total']*100):0 ?>%</td><td><?=e($r['created_at'])?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4">Aún no has realizado actividades.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/../partials/footer.php'; ?>